pub fn unrank_into(&self, ordinal: usize, output: &mut [usize]) -> Result<(), FinitePiError> {

    finite_pi_work(self.fiber_sizes.len(), 4, self.limits.max_work)?;
    if ordinal >= self.cardinality {
        return Err(FinitePiError::Ordinal {
